use super::{Clip, Pose};

pub(super) const CROSSED: &str = "Static_up/static.png";
pub(super) const UNCROSSED: &str = "Static_up/uncrossed.png";
pub(super) const HEADSET: &str = "Headset_up/static.png";
pub(super) const READING: &str = "Static_up/reading-book-v2.png";
pub(super) const TYPING: &str = "Freestyle_up/wireless-keyboard/frame_03.png";

macro_rules! clip {
    ($id:literal, $entry:ident -> $exit:ident, $first:expr, $dir:literal, $last:expr, $durations:expr) => {
        Clip {
            id: $id,
            entry: Pose::$entry,
            exit: Pose::$exit,
            frames: &[
                $first,
                concat!($dir, "/frame_02.png"),
                concat!($dir, "/frame_03.png"),
                concat!($dir, "/frame_04.png"),
                concat!($dir, "/frame_05.png"),
                concat!($dir, "/frame_06.png"),
                concat!($dir, "/frame_07.png"),
                concat!($dir, "/frame_08.png"),
                $last,
            ],
            durations: &$durations,
        }
    };
}

